using FluentAssertions;
using Microsoft.VisualStudio.TestPlatform.Utilities;
using Newtonsoft.Json.Linq;
using PopApiValidations.Swashbuckle_Tests.Helpers;
using Xunit.Abstractions;

namespace PopApiValidations.Swashbuckle_Tests.HelperTests_TestProject;

public class JsonCompareTests
{
    private readonly ITestOutputHelper output;

    public JsonCompareTests(ITestOutputHelper output)
    {
        this.output = output;
    }

    [Fact]
    public void GivenASimpleObject_ItDetectsAPropertyChange()
    {
        // Arrange 
        var obj1 = new JObject
        {
            ["Id"] = 1,
            ["Name"] = "Alice",
            ["Active"] = true
        };

        var obj2 = new JObject
        {
            ["Id"] = 1,
            ["Name"] = "Alice1",
            ["Active"] = true
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("+").And.Contain("-");
    }

    [Fact]
    public void GivenASimpleObject_ItDetectsAnAddedProperty()
    {
        // Arrange 
        var obj1 = new JObject
        {
            ["Id"] = 1,
            ["Name"] = "Alice",
            ["Active"] = true
        };

        var obj2 = new JObject
        {
            ["Id"] = 1,
            ["Name"] = "Alice",
            ["Active"] = true,
            ["Age"] = 30
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("-");
    }

    [Fact]
    public void GivenASimpleObjectHoldingAnArray_ItDetectsAPropertyChange()
    {
        // Arrange
        var obj1 = new JObject
        {
            ["Group"] = "Admins",
            ["Members"] = new JArray("Alice", "Bob", "Charlie2")
        };

        var obj2 = new JObject
        {
            ["Group"] = "Admins",
            ["Members"] = new JArray("Alice", "Bob", "Charlie")
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("+").And.Contain("-");
    }

    [Fact]
    public void GivenASimpleObjectHoldingAnArray_ItDetectsAnADdedItem()
    {
        // Arrange
        var obj1 = new JObject
        {
            ["Group"] = "Admins",
            ["Members"] = new JArray("Alice", "Bob", "Charlie")
        };

        var obj2 = new JObject
        {
            ["Group"] = "Admins",
            ["Members"] = new JArray("Alice", "Bob", "Charlie", "George")
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("-");
    }

    [Fact]
    public void GivenASimpleArrayHoldingObjects_ItDetectsAPropertyChange()
    {
        // Arrange
        var obj1 = new JArray(
            new JObject
            {
                ["Id"] = 1,
                ["Name"] = "Alice"
            },
            new JObject
            {
                ["Id"] = 2,
                ["Name"] = "Bob"
            }
        );

        var obj2 = new JArray(
            new JObject
            {
                ["Id"] = 1,
                ["Name"] = "Alice"
            },
            new JObject
            {
                ["Id"] = 2,
                ["Name"] = "Bob3"
            }
        );

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("+").And.Contain("-");
    }

    [Fact]
    public void GivenASimpleArrayHoldingObjects_ItDetectsAnAddedProperty()
    {
        // Arrange
        var obj1 = new JArray(
            new JObject
            {
                ["Id"] = 1,
                ["Name"] = "Alice"
            },
            new JObject
            {
                ["Id"] = 2,
                ["Name"] = "Bob"
            }
        );

        var obj2 = new JArray(
            new JObject
            {
                ["Id"] = 1,
                ["Name"] = "Alice",
                ["Age"] = 30
            },
            new JObject
            {
                ["Id"] = 2,
                ["Name"] = "Bob"
            }
        );

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("-");
    }

    [Fact]
    public void Given3ObjectsDeep_ItDetectsAPropertyChange()
    {
        // Arrange
        var obj1 = new JObject
        {
            ["User"] = new JObject
            {
                ["Id"] = 1,
                ["Profile"] = new JObject
                {
                    ["Email"] = "alice@example.com",
                    ["Verified"] = true
                }
            },
            ["Role"] = "Admin"
        };

        var obj2 = new JObject
        {
            ["User"] = new JObject
            {
                ["Id"] = 1,
                ["Profile"] = new JObject
                {
                    ["Email"] = "alice@example.com3",
                    ["Verified"] = true
                }
            },
            ["Role"] = "Admin"
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("+").And.Contain("-");
    }

    [Fact]
    public void Given3ObjectsDeep_ItDetectsAnRemovedProperty()
    {
        // Arrange
        var obj1 = new JObject
        {
            ["User"] = new JObject
            {
                ["Id"] = 1,
                ["Profile"] = new JObject
                {
                    ["Email"] = "alice@example.com",
                    ["Verified"] = true
                }
            },
            ["Role"] = "Admin"
        };

        var obj2 = new JObject
        {
            ["User"] = new JObject
            {
                ["Id"] = 1,
                ["Profile"] = new JObject
                {
                    ["Email"] = "alice@example.com3",
                    ["Verified"] = true,
                    ["Google"] = "tired"
                }
            },
            ["Role"] = "Admin"
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("-");
    }

    [Fact]
    public void Given3ObjectsDeep_ItDetectsAnAddedProperty()
    {
        // Arrange
        var obj1 = new JObject
        {
            ["User"] = new JObject
            {
                ["Id"] = 1,
                ["Profile"] = new JObject
                {
                    ["Email"] = "alice@example.com",
                    ["Verified"] = true,
                    ["Google"] = "tired"
                }
            },
            ["Role"] = "Admin"
        };

        var obj2 = new JObject
        {
            ["User"] = new JObject
            {
                ["Id"] = 1,
