                {
                    ["Email"] = "alice@example.com3",
                    ["Verified"] = true,
                }
            },
            ["Role"] = "Admin"
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("+");
    }

    [Fact]
    public void GivenAnObjectHoldingAnArrayOfObjects_ItDetectsAPropertyChange()
    {
        // Arrange
        var obj1 = new JObject
        {
            ["Team"] = "Developers",
            ["Members"] = new JArray(
                new JObject
                {
                    ["Id"] = 1,
                    ["Name"] = "Alice"
                },
                new JObject
                {
                    ["Id"] = 2,
                    ["Name"] = "Bob"
                }
            )
        };

        var obj2 = new JObject
        {
            ["Team"] = "Developers",
            ["Members"] = new JArray(
                new JObject
                {
                    ["Id"] = 1,
                    ["Name"] = "Alice"
                },
                new JObject
                {
                    ["Id"] = 2,
                    ["Name"] = "Bob5"
                }
            )
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().Contain("+").And.Contain("-");
    }

    [Fact]
    public void GivenAnObjectHoldingAnArrayOfObjects_ItDetectsAnAddedProperty()
    {
        // Arrange
        var obj1 = new JObject
        {
            ["Team"] = "Developers",
            ["Members"] = new JArray(
                new JObject
                {
                    ["Id"] = 1,
                    ["Name"] = "Alice",
                    ["Image"] = new JObject{
                        ["Dog"] = new JObject{
                            ["Type"] = "Bulldog"
                        }
                    }
                },
                new JObject
                {
                    ["Id"] = 2,
                    ["Name"] = "Bob"
                }
            )
        };

        var obj2 = new JObject
        {
            ["Team"] = "Developers",
            ["Members"] = new JArray(
                new JObject
                {
                    ["Id"] = 1,
                    ["Name"] = "Alice",
                },
                new JObject
                {
                    ["Id"] = 2,
                    ["Name"] = "Bob"
                }
            )
        };

        // Act
        var differences = JsonCompare.FindDiffString(obj1, obj2);

        //Assert
        Assert.NotEmpty(differences);
        differences.Should().NotContain("+").And.NotContain("-");
    }

